class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t):
            return False

        cycles, extra = divmod(k, 26)
        shifts = [cycles + (shift <= extra) for shift in range(26)]

        for cs, ct in zip(s, t):
            shift = (ord(ct) - ord(cs)) % 26
            if shift == 0:
                continue
            if not shifts[shift]:
                return False
            shifts[shift] -= 1

        return True

class Solution:
    def minInsertions(self, s: str) -> int:
        leftbrackets = insertions = 0
        i, n = 0, len(s)

        while i < n:
            if s[i] == '(':
                leftbrackets += 1
            elif s[i] == ')':
                if i == n-1 or s[i+1] != ')': insertions += 1
                else: i += 1

                if not leftbrackets: insertions += 1
                else: leftbrackets -= 1

            i += 1

        return leftbrackets * 2 + insertions

class Solution:
    def findKthBit(self, n: int, k: int) -> str:
        i, s, hash_map = 1, '0', {'1': '0', '0': '1'}
        for i in range(1, n):
            s = s + '1' + ''.join((hash_map[i] for i in s))[::-1]
        return s[k-1]

